window.BRAIN_QUESTIONS=[{"id":"A-L1","pack":"A","category":"logic","prompt":"约定：如果列车晚点，小周就改乘巴士。今天小周没有改乘巴士。哪句话一定成立？","options":["列车晚点了","小周改乘了地铁","列车没有晚点","无法判断列车是否晚点"],"answer":2,"explanation":"若晚点就会乘巴士；没有乘巴士，因此没有晚点。"},{"id":"A-L2","pack":"A","category":"logic","prompt":"四人依次进入房间：甲早于丙，丙早于乙，乙早于丁。哪种顺序符合全部条件？","options":["甲、乙、丙、丁","丙、甲、乙、丁","丁、甲、丙、乙","甲、丙、乙、丁"],"answer":3,"explanation":"条件连起来是甲＜丙＜乙＜丁。"},{"id":"A-L3","pack":"A","category":"logic","prompt":"徽章只在红、蓝、绿三个盒子中的一个。红盒写“在蓝盒”，蓝盒写“在绿盒”，绿盒写“不在蓝盒”。三句话恰好两句为真。徽章在哪？","options":["绿盒","红盒","蓝盒","无法确定"],"answer":0,"explanation":"放在绿盒时，蓝盒和绿盒的话为真，红盒的话为假。"},{"id":"A-L4","pack":"A","category":"logic","prompt":"甲比乙重，乙比丙重；丁比甲轻，但比丙重。谁一定最重？","options":["甲","乙","丙","丁"],"answer":0,"explanation":"甲重于乙和丁；乙重于丙，因此甲最重。"},{"id":"A-N1","pack":"A","category":"numeric","prompt":"一件外套原价 180 元。只能二选一：打八折，或立减 30 元。哪种更便宜？","options":["立减，实付 150 元","八折，实付 144 元","两种一样","条件不足"],"answer":1,"explanation":"180×0.8＝144 元；180－30＝150 元。"},{"id":"A-N2","pack":"A","category":"numeric","prompt":"周一卖出 40 杯，退了 4 杯；周二卖出 30 杯，退了 6 杯。哪天退单率更低？","options":["周一","周二","一样","只知道数量，算不出"],"answer":0,"explanation":"周一 4/40＝10%；周二 6/30＝20%。"},{"id":"A-N3","pack":"A","category":"numeric","prompt":"甲单独完成一份工作要 6 分钟，乙要 9 分钟。两人同时做，多久完成？","options":["3 分钟","3 分 36 秒","4 分 30 秒","7 分 30 秒"],"answer":1,"explanation":"合做速度是每分钟 1/6＋1/9＝5/18 份，完成需 18/5＝3.6 分钟。"},{"id":"A-N4","pack":"A","category":"numeric","prompt":"三种糖果数量满足 A:B＝2:3，B:C＝4:5。A:C 是多少？","options":["2:5","3:4","10:12","8:15"],"answer":3,"explanation":"A/C＝(A/B)×(B/C)＝(2/3)×(4/5)＝8/15。"},{"id":"A-C1","pack":"A","category":"reading","prompt":"公告说：“只有完成验证，才能领取徽章。”哪句话一定符合公告？","options":["完成验证就一定能领取","没领取的人一定没验证","能领取的人已经完成验证","所有人都能领取"],"answer":2,"explanation":"验证是领取的必要条件，不是充分条件。"},{"id":"A-C2","pack":"A","category":"reading","prompt":"一项调查发现，经常跑步的人平均睡得更久；调查没有记录工作时间。最稳妥的表述是什么？","options":["跑步一定让人多睡","两者有关联，但不能由此确定因果","睡得久一定让人跑步","工作时间肯定没有影响"],"answer":1,"explanation":"观察到关联；未控制的因素和反向因果仍可能存在。"},{"id":"A-C3","pack":"A","category":"reading","prompt":"“并非所有人都没收到通知。”这句话至少说明什么？","options":["所有人都收到了","没人收到","恰好一人收到","至少一人收到了"],"answer":3,"explanation":"否定“所有人都没收到”，得到“至少一人收到”。"},{"id":"A-C4","pack":"A","category":"reading","prompt":"报道说：“有些零糖饮料仍使用其他甜味剂。”据此能推出什么？","options":["零糖不必然意味着没有甜味剂","所有零糖饮料都很甜","甜味剂一定含糖","零糖饮料都不甜"],"answer":0,"explanation":"“有些”只支持存在这样的零糖饮料，不能推广到全部。"},{"id":"A-R1","pack":"A","category":"rules","prompt":"验证码必须以 B 开头、恰好 4 位，而且末位是偶数。选出符合条件的一项。","options":["B4A3","A4B2","B4A2","B42"],"answer":2,"explanation":"B4A2 满足开头、长度和末位三个条件。"},{"id":"A-R2","pack":"A","category":"rules","prompt":"处理输入“ A B C ”：先删掉所有空格，再把最后一个字母移到最前。结果是什么？","options":["ABC","CBA","CAB","BAC"],"answer":2,"explanation":"删空格得 ABC，把 C 移到最前得到 CAB。"},{"id":"A-R3","pack":"A","category":"rules","prompt":"标记留言：含“急”标红；但只要含“已完成”，一律标绿，且这条优先。留言“急件已完成”标什么色？","options":["红","绿","灰","同时红绿"],"answer":1,"explanation":"两条都触发时，已完成的绿色规则优先。"},{"id":"A-R4","pack":"A","category":"rules","prompt":"从 [A2、B4、A5、C6] 中选出“首字母为 A 或 B，且数字为偶数”的全部项目。","options":["A2、B4、C6","A2、A5","B4、A5","A2、B4"],"answer":3,"explanation":"A2 和 B4 同时满足两项条件。"},{"id":"B-L1","pack":"B","category":"logic","prompt":"如果下雨，天台就会湿。现在天台湿了。能确定下雨了吗？","options":["能，一定下雨了","不能，天台也可能因别的原因变湿","能，一定没下雨","只有晚上才不能确定"],"answer":1,"explanation":"“下雨会湿”不等于“湿了必定下雨”。"},{"id":"B-L2","pack":"B","category":"logic","prompt":"规则：卡片正面若是蓝色，背面必须是偶数。桌上可见四张卡的一面：蓝色、红色、4、5。为检查规则，至少翻哪两张？","options":["蓝色和 4","红色和 4","红色和 5","蓝色和 5"],"answer":3,"explanation":"要看蓝色背面是否偶数，也要看 5 的另一面是否蓝色。"},{"id":"B-L3","pack":"B","category":"logic","prompt":"甲、乙、丙、丁排队。甲在丙前，丙在丁前，乙在丁后。谁一定排最后？","options":["甲","丙","乙","丁"],"answer":2,"explanation":"条件串起来是甲＜丙＜丁＜乙。"},{"id":"B-L4","pack":"B","category":"logic","prompt":"A、B、C、D 四盏灯恰好亮两盏。D 没亮；A 亮时 B 必须灭；C 亮时 A 必须亮。哪两盏亮？","options":["A 和 B","A 和 C","B 和 C","B 和 D"],"answer":1,"explanation":"若 C 不亮，只能 A、B 同亮，但违反条件；所以 C 亮，进而 A 亮。"},{"id":"B-N1","pack":"B","category":"numeric","prompt":"价格先上涨 20%，再从新价格下降 20%。原价 100 元，现价多少？","options":["80 元","100 元","96 元","104 元"],"answer":2,"explanation":"100×1.2×0.8＝96 元。"},{"id":"B-N2","pack":"B","category":"numeric","prompt":"3 人的平均分是 80 分，第 4 人得 100 分。4 人平均分是多少？","options":["85 分","82 分","90 分","95 分"],"answer":0,"explanation":"总分为 3×80＋100＝340；340/4＝85。"},{"id":"B-N3","pack":"B","category":"numeric","prompt":"买 5 张每张 24 元的票。只能选一种活动：“每买 3 张只付 2 张的钱”，或“全部九折”。选哪种更省？","options":["前者，省 24 元","九折，省 12 元","两者一样","前者，省 12 元"],"answer":3,"explanation":"买三付二时付 4×24＝96 元；九折付 108 元，前者再省 12 元。"},{"id":"B-N4","pack":"B","category":"numeric","prompt":"抽奖券每张 5 元。10 张中有 2 张各能得到 30 元，其余没有奖金。随机买 1 张，净收益的平均值是多少？","options":["亏 5 元","赚 1 元","赚 6 元","赚 25 元"],"answer":1,"explanation":"预期奖金为 2/10×30＝6 元；扣除 5 元票价，净收益均值为 1 元。"},{"id":"B-C1","pack":"B","category":"reading","prompt":"报名要求“团队人数不少于 3 人”。哪个团队符合人数要求？","options":["2 人","最多 2 人","恰好 3 人","人数未知的团队一定符合"],"answer":2,"explanation":"不少于 3 人包括 3 人。"},{"id":"B-C2","pack":"B","category":"reading","prompt":"“这项计划并非没有可能成功。”与哪种说法最接近？","options":["一定成功","一定失败","有成功的可能，但并不保证","成功与否已确定"],"answer":2,"explanation":"双重否定表示存在可能，不能推出必然。"},{"id":"B-C3","pack":"B","category":"reading","prompt":"一篇文章调查了某城市的 50 名骑行者，发现多数人喜欢夜骑。以下哪句超出了调查能支持的范围？","options":["全国骑行者多数喜欢夜骑","受访骑行者中，多数喜欢夜骑","样本来自一座城市","调查人数是 50"],"answer":0,"explanation":"单城小样本不能直接推出全国骑行者的情况。"},{"id":"B-C4","pack":"B","category":"reading","prompt":"店主说：“这款饼干本周没有比上周涨价。”仅凭这句话，哪件事不能确定？","options":["这周肯定降价了","这周价格没有高于上周","这周价格可能与上周相同","这周价格可能低于上周"],"answer":0,"explanation":"没有涨价也可能是价格不变。"},{"id":"B-R1","pack":"B","category":"rules","prompt":"只处理“同时含 #、且不含 @”的留言。哪条会被处理？","options":["#@你好","#你好","你好@","你好"],"answer":1,"explanation":"只有第一条同时满足两个条件。"},{"id":"B-R2","pack":"B","category":"rules","prompt":"处理代码 AB12：取数字部分加 3，再接上原代码的首字母。结果是什么？","options":["AB15","A15","12A3","15A"],"answer":3,"explanation":"数字是 12，加 3 得 15，再接首字母 A，得到 15A。"},{"id":"B-R3","pack":"B","category":"rules","prompt":"排班标记：周末标“休”；值班标“班”且优先于周末；法定假日一律标“休”且优先级最高。某人法定假日恰好值班，应标什么？","options":["班","同时班和休","无法判断","休"],"answer":3,"explanation":"法定假日规则优先级最高，标“休”。"},{"id":"B-R4","pack":"B","category":"rules","prompt":"对 a2b3c 依次执行：所有字母变大写；删除数字；只保留前两位。结果是什么？","options":["AB","A2","BC","ABC"],"answer":0,"explanation":"A2B3C → ABC → AB。"},{"id":"C-L1","pack":"C","category":"logic","prompt":"只有一人拿了钥匙。甲说“乙拿了”；乙说“丙拿了”；丙说“我没拿”。三句话恰好两句为真。谁拿了钥匙？","options":["甲","丙","无法确定","乙"],"answer":3,"explanation":"乙拿时，甲和丙说真话，乙说假话，恰好两真。"},{"id":"C-L2","pack":"C","category":"logic","prompt":"五个座位从左到右排成一行。甲坐最左，丁坐最右；乙紧挨甲右边，丙紧挨丁左边。正中坐谁？","options":["戊","乙","丙","无法确定"],"answer":0,"explanation":"座位依次为甲、乙、戊、丙、丁。"},{"id":"C-L3","pack":"C","category":"logic","prompt":"甲乙丙丁中只有一人拿走饼干，四人恰好一句假话。甲说“乙拿的”；乙说“丙拿的”；丙说“乙没拿”；丁说“丁没拿”。谁拿的？","options":["丙","甲","乙","丁"],"answer":0,"explanation":"丙拿时，只有甲说假话，其余三句都为真。"},{"id":"C-L4","pack":"C","category":"logic","prompt":"A、B、C 三个方案恰好两个通过。A 通过就意味着 B 不通过；B 通过就意味着 C 不通过；已知 C 通过。通过的是哪两个？","options":["A 和 B","A 和 C","B 和 C","无法确定"],"answer":1,"explanation":"C 已通过，所以 B 不能通过；要满足恰好两个通过，A 必须通过。"},{"id":"C-N1","pack":"C","category":"numeric","prompt":"1000 件产品中有 10 件坏的。检测报坏的包括 9 件真坏品和 99 件好品。被报坏的产品中，真坏品约占多少？","options":["0.9%","50%","8.3%","90%"],"answer":2,"explanation":"报坏共 108 件，其中真坏 9 件；9/108≈8.3%。"},{"id":"C-N2","pack":"C","category":"numeric","prompt":"去程和回程距离相同，去程时速 30 公里，回程时速 60 公里。往返平均时速是多少？","options":["45 公里","40 公里","50 公里","60 公里"],"answer":1,"explanation":"同距离平均速度为 2/(1/30＋1/60)＝40 公里/小时。"},{"id":"C-N3","pack":"C","category":"numeric","prompt":"A 组 60 人，正确率 50%；B 组 40 人，正确率 75%。两组合起来的正确率是多少？","options":["55%","62.5%","60%","65%"],"answer":2,"explanation":"答对 60×50%＋40×75%＝60 人，总共 100 人，正确率 60%。"},{"id":"C-N4","pack":"C","category":"numeric","prompt":"水池原本为空。甲管单开 4 小时注满，乙管单开 6 小时注满，排水管单开 12 小时排空。三管同时开，几小时注满？","options":["3 小时","2 小时","4 小时","6 小时"],"answer":0,"explanation":"每小时净注入 1/4＋1/6－1/12＝1/3 池，因此需 3 小时。"},{"id":"C-C1","pack":"C","category":"reading","prompt":"“这本书得过奖，但并非所有获奖书都受欢迎。”能推出这本书受欢迎吗？","options":["能，一定受欢迎","能，一定不受欢迎","不能确定","只有作者知道"],"answer":2,"explanation":"部分获奖书不受欢迎，并不能确定眼前这本属于哪一类。"},{"id":"C-C2","pack":"C","category":"reading","prompt":"通知写着：“除非天气转晴，否则活动改在线上。”现在天气没有转晴。按通知应怎样举行？","options":["在线下","取消活动","无法确定","在线上"],"answer":3,"explanation":"没有转晴时，“否则”的线上方案适用。"},{"id":"C-C3","pack":"C","category":"reading","prompt":"报道称：甲方案首月收费低于乙，但两年总费用高于乙。哪句是恰当概括？","options":["甲始终更省","乙首月更便宜","两种方案两年花费相同","短期便宜不代表长期便宜"],"answer":3,"explanation":"甲首月较便宜，但两年总费用更高。"},{"id":"C-C4","pack":"C","category":"reading","prompt":"“所有提交者都收到了回执；收到回执的人未必都提交了。”小张收到了回执。能确定小张提交了吗？","options":["能，一定提交了","不能确定","能，一定没提交","只有回执日期能决定"],"answer":1,"explanation":"提交可以推出有回执；有回执不能反推一定提交。"},{"id":"C-R1","pack":"C","category":"rules","prompt":"处理数字 [2、5、8]：偶数乘 2，奇数不变；然后按从大到小排列。结果是什么？","options":["16、4、5","8、5、2","16、5、4","5、4、16"],"answer":2,"explanation":"先得到 [4、5、16]，降序为 [16、5、4]。"},{"id":"C-R2","pack":"C","category":"rules","prompt":"留言含“退款”标为“待处理”；含“已解决”标为“完成”。两者同时出现时，“完成”优先。留言“退款问题已解决”标什么？","options":["完成","待处理","两种标签","不标记"],"answer":0,"explanation":"两条都匹配时按优先级选择“完成”。"},{"id":"C-R3","pack":"C","category":"rules","prompt":"对 aB3c 依次执行：删掉数字；把前两个字符互换；其余字符保持原位和大小写。结果是什么？","options":["Bca","Abc","aBc","Bac"],"answer":3,"explanation":"删数字得 aBc，交换 a 与 B 后得到 Bac。"},{"id":"C-R4","pack":"C","category":"rules","prompt":"处理名单 [猫*、狗、鸟*、鱼、鹿]：先删除带 * 的项，再按原顺序取剩余的第 2 项。选中谁？","options":["狗","鱼","鸟","鹿"],"answer":1,"explanation":"删除猫*和鸟*后是 [狗、鱼、鹿]，第 2 项为鱼。"},{"id":"D-L1","pack":"D","category":"logic","prompt":"约定：画室的灯亮着，当且仅当值班员在场。现在灯没有亮。哪句话一定成立？","options":["值班员不在场","值班员正在休息","画室已经关门","灯泡坏了"],"answer":0,"explanation":"按题设，灯亮与值班员在场是双向条件；灯不亮就表示值班员不在场。"},{"id":"D-L2","pack":"D","category":"logic","prompt":"四人从左到右排队：丁在甲左边，甲在乙左边，丙紧挨乙的右边。哪种顺序符合条件？","options":["丁、乙、甲、丙","丁、甲、乙、丙","甲、丁、乙、丙","丁、甲、丙、乙"],"answer":1,"explanation":"必须先有丁＜甲＜乙，且丙紧挨乙的右边，所以顺序是丁、甲、乙、丙。"},{"id":"D-L3","pack":"D","category":"logic","prompt":"比赛只有甲、乙两队，且恰好一队获胜。若甲获胜，舞台灯就变绿。现在舞台灯没变绿。哪句话一定成立？","options":["甲获胜","比赛取消","乙获胜","两队平局"],"answer":2,"explanation":"灯没变绿可推出甲没有获胜；题设又说恰好一队获胜，所以乙获胜。"},{"id":"D-L4","pack":"D","category":"logic","prompt":"甲、乙、丙三人各拿一枚不同颜色的贴纸：红、绿、黄。甲不拿红，乙拿绿。甲拿什么颜色？","options":["红","绿","无法确定","黄"],"answer":3,"explanation":"绿已给乙，甲又不拿红，只能拿黄。"},{"id":"D-N1","pack":"D","category":"numeric","prompt":"一本画册标价 120 元，先打九折，再减 10 元。最后付多少？","options":["98 元","100 元","108 元","110 元"],"answer":0,"explanation":"120×0.9－10＝98 元。"},{"id":"D-N2","pack":"D","category":"numeric","prompt":"共有 20 张入场券，其中儿童票占 3/5。成人票有几张？","options":["6 张","8 张","12 张","15 张"],"answer":1,"explanation":"儿童票 20×3/5＝12 张，成人票 20－12＝8 张。"},{"id":"D-N3","pack":"D","category":"numeric","prompt":"小店前三天分别卖出 12、15、? 杯饮料，三天平均每天 17 杯。第三天卖出多少杯？","options":["17 杯","21 杯","24 杯","27 杯"],"answer":2,"explanation":"三天合计 17×3＝51 杯；第三天 51－12－15＝24 杯。"},{"id":"D-N4","pack":"D","category":"numeric","prompt":"有 5 种不同口味的糖果，任选 2 种组成一包，不考虑挑选顺序。能组成多少种不同的包？","options":["5 种","8 种","20 种","10 种"],"answer":3,"explanation":"每两种口味组成一包，共 5×4÷2＝10 种。"},{"id":"D-C1","pack":"D","category":"reading","prompt":"通知说：通过面试者可以申请试训，但参加试训还须体检合格。小林通过了面试。哪种说法最稳妥？","options":["还不能断定小林能参加试训","小林一定能参加试训","小林一定体检合格","小林无需申请试训"],"answer":0,"explanation":"面试通过并不满足参加试训的全部条件，还需要体检合格。"},{"id":"D-C2","pack":"D","category":"reading","prompt":"一家店本月销量上涨，同期既改了网店页面，也新开了一家线下门店。仅凭这些信息，哪种说法正确？","options":["销量上涨全因网店改版","不能确定上涨全由网店改版造成","新门店一定没有贡献","销量实际上没有上涨"],"answer":1,"explanation":"两项变化同时发生，不能把销量增长全部归因于其中一项。"},{"id":"D-C3","pack":"D","category":"reading","prompt":"“所有画都是蓝色的”这句话如果是假的，哪句话一定是真的？","options":["所有画都不是蓝色的","恰好一幅画不是蓝色的","至少一幅画不是蓝色的","至少一幅画是蓝色的"],"answer":2,"explanation":"全称陈述为假，说明至少存在一幅反例，但不能推出反例有几幅。"},{"id":"D-C4","pack":"D","category":"reading","prompt":"馆内公告：周六通常开放；遇到设备维护时可能临时闭馆。只知道今天是周六，能断定什么？","options":["今天一定开放","今天一定闭馆","今天没有设备维护","不能断定今天一定开放"],"answer":3,"explanation":"“通常”允许例外，周六仍可能因维护而临时闭馆。"},{"id":"D-R1","pack":"D","category":"rules","prompt":"对 [5、8、3、12、10] 先只保留偶数，再按原顺序选第 2 项。选中哪个数？","options":["12","8","10","3"],"answer":0,"explanation":"保留偶数得到 [8、12、10]，第 2 项是 12。"},{"id":"D-R2","pack":"D","category":"rules","prompt":"标题含 # 就加“主题”标签；若同时含 [隐藏]，则优先设为“不可见”。标题“#春日[隐藏]”最终怎样处理？","options":["只加主题标签","设为不可见","同时显示主题和隐藏","不做处理"],"answer":1,"explanation":"两条规则都命中，但 [隐藏] 的优先级更高。"},{"id":"D-R3","pack":"D","category":"rules","prompt":"处理“AbC3”：先删掉数字，再全部转小写，最后把首字母移到末尾。结果是？","options":["abc","cab","bca","acb"],"answer":2,"explanation":"AbC3→AbC→abc→bca。"},{"id":"D-R4","pack":"D","category":"rules","prompt":"合格票号必须以 K 开头，后接恰好三位数字，且三位数字之和为偶数。哪一个合格？","options":["K124","K531","K42","K204"],"answer":3,"explanation":"K204 以 K 开头、后接三位数字，2＋0＋4＝6 为偶数。"},{"id":"E-L1","pack":"E","category":"logic","prompt":"如果书包里有雨伞，就会带水壶；如果带水壶，桌上就会有贴纸。现在桌上没有贴纸，哪句话一定成立？","options":["书包里有雨伞","桌上有水壶","书包里没有雨伞","今天没有下雨"],"answer":2,"explanation":"没有贴纸推出没有带水壶；没有带水壶又推出书包里没有雨伞。"},{"id":"E-L2","pack":"E","category":"logic","prompt":"甲、乙、丙各选一种不同水果：苹果、梨、桃。甲不要苹果，乙选桃，丙不要梨。甲选什么？","options":["苹果","桃","无法确定","梨"],"answer":3,"explanation":"乙选桃；剩下苹果和梨，甲不选苹果，所以甲选梨。"},{"id":"E-L3","pack":"E","category":"logic","prompt":"奖品在左、右两盒之一。甲说“在左盒”，乙说“不在左盒”。已知恰好一句是真话。奖品在哪？","options":["仍无法确定","一定在左盒","一定在右盒","两个盒子都有"],"answer":0,"explanation":"两句话互为否定，不论奖品在哪，都恰好一句真话。"},{"id":"E-L4","pack":"E","category":"logic","prompt":"小猫比小狗早到；兔子在小狗之后到；仓鼠也在兔子之前到。谁一定都比兔子先到？","options":["只有小狗","小猫、小狗和仓鼠","只有小猫和仓鼠","只有仓鼠"],"answer":1,"explanation":"小猫早于小狗，小狗早于兔子；仓鼠也早于兔子，所以三者都先于兔子。"},{"id":"E-N1","pack":"E","category":"numeric","prompt":"两杯果汁每杯 12 元，三杯奶茶每杯 18 元。五杯饮品的平均单价是多少？","options":["15 元","16 元","15.6 元","18 元"],"answer":2,"explanation":"总价 2×12＋3×18＝78 元，平均每杯 78÷5＝15.6 元。"},{"id":"E-N2","pack":"E","category":"numeric","prompt":"骑车人先以每小时 60 公里走 1.5 小时，再以每小时 40 公里走 0.5 小时。全程平均速度是多少？","options":["50 公里/时","60 公里/时","52 公里/时","55 公里/时"],"answer":3,"explanation":"总路程 60×1.5＋40×0.5＝110 公里，总时间 2 小时，平均 55 公里/时。"},{"id":"E-N3","pack":"E","category":"numeric","prompt":"一件商品打八折后是 96 元，原价是多少？","options":["120 元","112 元","116 元","128 元"],"answer":0,"explanation":"打八折表示付原价的 80%，原价为 96÷0.8＝120 元。"},{"id":"E-N4","pack":"E","category":"numeric","prompt":"300 毫升饮品中，茶与奶的体积比为 1:2。再加入 100 毫升茶，新的茶奶比是多少？","options":["2:3","1:1","1:2","2:1"],"answer":1,"explanation":"原来茶 100 毫升、奶 200 毫升；加茶后各 200 毫升，比为 1:1。"},{"id":"E-C1","pack":"E","category":"reading","prompt":"告示写着：“只有已预约并收到确认短信的人，才可以进入展厅。”能进入展厅的人一定满足什么？","options":["只要预约即可","只要收到短信即可","已预约且收到确认短信","可以先入场后预约"],"answer":2,"explanation":"“只有……才……”给出进入展厅的两个必要条件，缺一不可。"},{"id":"E-C2","pack":"E","category":"reading","prompt":"旧版应用的老用户试用了新版，多数人说新版更好用；没有邀请新用户参与。最稳妥的结论是？","options":["所有人都觉得新版更好用","新用户一定不会喜欢新版","新版对每个人都更高效","这批参与试用的老用户多数更喜欢新版"],"answer":3,"explanation":"结论只能覆盖被调查的这批老用户，不能直接推广到新用户或所有人。"},{"id":"E-C3","pack":"E","category":"reading","prompt":"“并不是没人错过末班车。”这句话至少说明什么？","options":["至少有一人错过末班车","所有人都错过末班车","恰好一人错过末班车","没人错过末班车"],"answer":0,"explanation":"否定“没人错过”，得到“至少有人错过”。"},{"id":"E-C4","pack":"E","category":"reading","prompt":"手机指南写道：“低电量时，建议开启省电模式。”哪种理解最准确？","options":["低电量时必须开启","这是建议，不是强制要求","电量充足时禁止开启","开启后电量一定翻倍"],"answer":1,"explanation":"“建议”表达推荐做法，并未规定必须开启。"},{"id":"E-R1","pack":"E","category":"rules","prompt":"处理名单 [小明*、小红、小张*、小李]：先删除带 * 的名字，再把剩余名单倒序，取第 1 项。选中谁？","options":["小明","小红","小李","小张"],"answer":2,"explanation":"删除后是 [小红、小李]，倒序后第 1 项是小李。"},{"id":"E-R2","pack":"E","category":"rules","prompt":"对数字 5 按顺序执行：加 3、乘 2、减 4。结果是多少？","options":["8","10","14","12"],"answer":3,"explanation":"(5＋3)×2－4＝12。"},{"id":"E-R3","pack":"E","category":"rules","prompt":"从 [A2、B5*、A7、C9、B4] 中选出：以 A 或 B 开头、数字大于 3、且没有 * 的全部项目。","options":["A7、B4","B5*、A7、B4","A2、A7、B4","A7、C9"],"answer":0,"explanation":"A7、B4 同时满足三个条件；B5* 因带星号被排除。"},{"id":"E-R4","pack":"E","category":"rules","prompt":"密码须恰好 5 个字符，以 Q 开头，包含恰好一个数字，且末位是 !。哪一个符合？","options":["Qab23!","Qab2!","Qabc!","Q2ab?"],"answer":1,"explanation":"Qab2! 正好五个字符、以 Q 开头、一个数字且末位为 !。"}];
